def solve(s):
    """Return True iff brackets in *s* are balanced.
    Supports (), [], {}. Non‑bracket characters are ignored.
    If *s* is not iterable (e.g., ``None`` or an int), it is treated as having no brackets
    and therefore is considered balanced.
    """
    try:
        iterator = iter(s)
    except Exception:
        return True
    pairs = {')': '(', ']': '[', '}': '{'}
    opening = set(pairs.values())
    stack = []
    for ch in iterator:
        if ch in opening:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return not stack

